hostedSite.customCss:
.hs-hero { padding: 3.1rem 1.5rem 1.1rem; }
.hs-explain { padding: 0 1.5rem 0.5rem; max-width: 68rem; margin: 0 auto; text-align: center; }
.hs-explain .hs-features { padding: 1.15rem 0 0; }
.hs-roster { padding: 0.5rem 1.5rem 0.25rem; text-align: center; }
.hs-sql-slot { max-width: 46rem; margin: 1rem auto 0; }
.hs-split { padding-top: 0.35rem; padding-bottom: 3rem; }
.hs-split-heads { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1.25rem; max-width: 72rem; margin: 0 auto; padding: 1.5rem 1.25rem 0.35rem; text-align: center; }
.hs-split-heads > div { text-align: center; }
.hs-split-heads .hs-kicker, .hs-split-heads .hs-workspace-title { text-align: center; }
@media (max-width: 860px) { .hs-split-heads { grid-template-columns: 1fr; } }
